const char *
bro_message_code_wire (BroMessageCode code)
{
  g_return_val_if_fail ((int) code >= 0 && code < BRO_MSG_COUNT_, NULL);
  return codes[code];
}

gboolean
bro_message_code_parse (const char *text, BroMessageCode *out)
{
  for (int i = 0; text && i < BRO_MSG_COUNT_; i++)
    if (strcmp (codes[i], text) == 0) {
      *out = (BroMessageCode) i;
      return TRUE;
    }
  return FALSE;
}
